#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ilen = 0, ipos = 0;

static inline int gc() {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof ibuf, stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return ibuf[ipos++];
}

static long long readInt() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long v = 0;
    while (c >= '0' && c <= '9') {
        v = v * 10 + (c - '0');
        c = gc();
    }
    return neg ? -v : v;
}

static string readToken() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    string s;
    while (c > ' ') {
        s.push_back((char)c);
        c = gc();
    }
    return s;
}

int main() {
    string s = readToken();
    int minimum = 10;
    long long counts[10] = {0};
    for (int i = (int)s.size() - 1; i >= 0; i--) {
        int v = s[i] - '0';
        // A digit with a smaller digit to its right must be moved, which bumps it by one.
        if (v > minimum) counts[min(v + 1, 9)]++;
        else {
            counts[v]++;
            minimum = v;
        }
    }
    string out;
    for (int d = 0; d < 10; d++) out.append(counts[d], (char)('0' + d));
    puts(out.c_str());
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int minimum = 10;
        int[] counts = new int[10];
        for (int i = s.length() - 1; i >= 0; i--) {
            int v = s.charAt(i) - '0';
            if (v > minimum) counts[Math.min(v + 1, 9)]++;
            else {
                counts[v]++;
                minimum = v;
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int d = 0; d < 10; d++) for (int j = 0; j < counts[d]; j++) sb.append((char) ('0' + d));
        System.out.println(sb);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := token()
	minimum := 10
	var counts [10]int
	for i := len(s) - 1; i >= 0; i-- {
		v := int(s[i] - '0')
		if v > minimum {
			counts[min(v+1, 9)]++
		} else {
			counts[v]++
			minimum = v
		}
	}
	var sb strings.Builder
	for d := 0; d < 10; d++ {
		sb.WriteString(strings.Repeat(string(rune('0'+d)), counts[d]))
	}
	fmt.Println(sb.String())
}
